        float amount = fullNumber.floatValue();
        if (reference == DIALOG_STOCK_ADD) {
            stock = (stock == -1) ? amount : (stock + amount);
        } else if (reference == DIALOG_STOCK_REMOVE) {
            if (amount >= stock)
                stock = 0;
            else
                stock -= amount;
        }
        new ComputeEstimatedStockEndTask().execute();
